package com.oms.order.service;

import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderVirtualOutboundServiceTest {
    OrderShipmentServiceTest fixture=new OrderShipmentServiceTest();OrderVirtualOutboundService service;OrderShipmentDispatchService locks;OrderWarehouseClient inventory;OrderCatalog catalog;long shipment;Map<String,Object> stock;
    @BeforeAll static void start(){OrderShipmentServiceTest.setup();}
    Map<String,Object> row(Object...pairs){return fixture.row(pairs);}
    @BeforeEach void seed(){fixture.seed();catalog=mock(OrderCatalog.class);when(catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(row("wms_simulation_code","V1","owner_code","O1","real_store_code","R1","outbound_mode",2)));ReflectionTestUtils.setField(fixture.service,"catalog",catalog);ReflectionTestUtils.setField(fixture.business,"catalog",catalog);fixture.db.update("UPDATE oms_order SET allocation_policy=?",encode(row("owner_code","O1","allow_partial",1)));stock=fixture.receipt(1,10,"V1","R1");stock.put("outbound_quantity",0);stock.put("batch_code","B1");fixture.mirror(Arrays.asList(stock));shipment=number(fixture.generate(0).get(0),"id");fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='test',carrier_match_status='MATCHED',control_version=1");locks=new OrderShipmentDispatchService();ReflectionTestUtils.setField(locks,"repository",fixture.repository);inventory=mock(OrderWarehouseClient.class);when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenAnswer(i->R.ok(Arrays.asList(new LinkedHashMap<>(stock))));when(inventory.virtualReceipt(anyString(),anyString(),anyString())).thenReturn(R.ok(row("state","MISSING")));when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply(i.getArgument(1))));service=new OrderVirtualOutboundService();ReflectionTestUtils.setField(service,"repository",fixture.repository);ReflectionTestUtils.setField(service,"locks",locks);ReflectionTestUtils.setField(service,"inventory",inventory);ReflectionTestUtils.setField(service,"catalog",catalog);}
    @SuppressWarnings("unchecked") Map<String,Object> reply(Map<String,Object> p){List<Map<String,Object>> lines=new ArrayList<>();for(Map<String,Object> line:(List<Map<String,Object>>)p.get("lines")){Map<String,Object> r=new LinkedHashMap<>(line);r.put("outbound_quantity",number(line,"outbound_before")+number(line,"quantity"));lines.add(r);}return row("state","COMPLETED","request_id",p.get("request_id"),"shipment_sn",p.get("shipment_sn"),"quantity",p.get("quantity"),"lines",lines);}
    Map<String,Object> request(long version,long quantity){Map<String,Object> item=row("id",shipment,"control_version",version);if(quantity>=0)item.put("lines",Arrays.asList(row("id",fixture.db.queryForObject("SELECT id FROM oms_order_shipment_line",Long.class),"quantity",quantity)));return row("items",Arrays.asList(item));}
    Map<String,Object> submit(long version,long quantity){return service.submit("VERIFY",request(version,quantity),"tester").get(0);}
    Map<String,Object> document(){return fixture.service.detail("VERIFY",shipment);}
    Map<String,Object> task(){return fixture.db.queryForMap("SELECT * FROM oms_order_shipment_virtual_outbound ORDER BY id DESC LIMIT 1");}
    void due(){fixture.db.update("UPDATE oms_order_shipment_virtual_outbound SET next_attempt=NOW()");}
    @Test void partialThenFullUpdatesActualShipmentAndInventoryStatusesOnlyAfterReceipt(){assertEquals(true,document().get("can_virtual_outbound"));assertEquals(false,document().get("can_dispatch"));assertEquals(true,submit(1,4).get("success"));assertEquals("DISPATCHING",document().get("status"));assertEquals(0,number(document(),"shipped_quantity"));assertEquals(false,fixture.summary().get("can_void"));service.process("VERIFY",shipment);assertEquals("PART_SHIPPED",document().get("status"));assertEquals(4,number(document(),"shipped_quantity"));assertEquals("PART_SHIPPED",fixture.summary().get("business_status"));assertEquals("PART_OUTBOUND",fixture.summary().get("warehouse_inventory_status"));assertEquals("PART_CONSUMED",fixture.summary().get("logical_inventory_status"));assertEquals(6,number(fixture.summary(),"warehouse_occupied_quantity"));assertEquals(10,fixture.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));stock.put("outbound_quantity",4);assertEquals(true,submit(3,-1).get("success"));service.process("VERIFY",shipment);assertEquals("SHIPPED",document().get("status"));assertEquals("SHIPPED",fixture.summary().get("business_status"));assertEquals("OUTBOUND",fixture.summary().get("warehouse_inventory_status"));assertEquals("CONSUMED",fixture.summary().get("logical_inventory_status"));assertEquals(0,number(fixture.summary(),"warehouse_occupied_quantity"));assertEquals(2,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound WHERE state='COMPLETED'",Integer.class));}
    @Test void sameSubmissionIsIdempotentButChangedQuantityIsRejected(){assertEquals(true,submit(1,4).get("success"));assertEquals(true,submit(1,4).get("success"));assertEquals(false,submit(1,5).get("success"));assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound",Integer.class));assertEquals(2,number(document(),"control_version"));}
    @Test void lostPostReplyQueriesOriginalInventoryReceiptWithoutPostingAgain(){Map<String,Object>[] committed=new Map[1];when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenAnswer(i->{committed[0]=reply(i.getArgument(1));throw new IllegalStateException("response lost");});submit(1,4);service.process("VERIFY",shipment);assertEquals("UNKNOWN",task().get("state"));assertEquals(0,number(document(),"shipped_quantity"));fixture.db.update("UPDATE oms_order SET manual_hold=1");when(inventory.virtualReceipt(anyString(),anyString(),anyString())).thenAnswer(i->R.ok(committed[0]));due();service.process("VERIFY",shipment);verify(inventory,times(1)).virtualOutbound(anyString(),anyMap(),anyString());assertEquals(4,number(document(),"shipped_quantity"));assertEquals("COMPLETED",task().get("state"));}
    @Test void pendingHoldAndUnknownMissingReceiptCannotPostDuringHold(){submit(1,4);fixture.db.update("UPDATE oms_order SET manual_hold=1");service.process("VERIFY",shipment);assertEquals("PENDING",task().get("state"));verify(inventory,never()).virtualOutbound(anyString(),anyMap(),anyString());fixture.db.update("UPDATE oms_order SET manual_hold=0");when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException());due();service.process("VERIFY",shipment);assertEquals("UNKNOWN",task().get("state"));fixture.db.update("UPDATE oms_order SET manual_hold=1");due();service.process("VERIFY",shipment);verify(inventory,times(1)).virtualOutbound(anyString(),anyMap(),anyString());assertEquals("UNKNOWN",task().get("state"));assertEquals(false,service.reconcile("VERIFY",shipment,"tester").get("success"));}
    @Test void definitiveFailureRetriesOriginalSnapshotAndFreezesCarrierAndVoid(){submit(1,4);when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenReturn(R.fail("balance mismatch"));service.process("VERIFY",shipment);assertEquals("FAILED",task().get("state"));assertEquals(true,document().get("can_retry_virtual_outbound"));assertEquals(false,document().get("can_match_carrier"));assertEquals(false,fixture.summary().get("can_void"));String payload=text(task(),"payload_json");assertEquals(true,service.retry("VERIFY",shipment,3,"operator").get("success"));when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply(i.getArgument(1))));service.process("VERIFY",shipment);assertEquals(payload,task().get("payload_json"));assertEquals(4,number(document(),"shipped_quantity"));}
    @Test void wmsWarehousePartialRuleQuantityTenantAndSourceMismatchAreRejected(){fixture.db.update("UPDATE oms_order SET allocation_policy=?",encode(row("owner_code","O1","allow_partial",0)));assertEquals(false,submit(1,4).get("success"));assertEquals(false,submit(1,11).get("success"));assertEquals(false,service.submit("OTHER",request(1,10),"tester").get(0).get("success"));stock.put("outbound_quantity",1);assertEquals(false,submit(1,10).get("success"));stock.put("outbound_quantity",0);when(catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(row("wms_simulation_code","V1","owner_code","O1","real_store_code","R1","outbound_mode",1)));assertEquals(false,submit(1,10).get("success"));verify(inventory,never()).virtualOutbound(anyString(),anyMap(),anyString());}
    @Test void badReceiptRollsBackEveryLocalLineUpdate(){submit(1,4);when(inventory.virtualOutbound(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply(i.getArgument(1));((List<Map<String,Object>>)reply.get("lines")).add(row("allocation_id",999));return R.ok(reply);});service.process("VERIFY",shipment);assertEquals("UNKNOWN",task().get("state"));assertEquals(0,number(document(),"shipped_quantity"));assertEquals("DISPATCHING",document().get("status"));}
    @Test void concurrentSameVersionQueuesOneCommand() throws Exception {ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Map<String,Object>>> jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();return submit(1,4);}));start.countDown();for(Future<Map<String,Object>> job:jobs)assertEquals(true,job.get(15,TimeUnit.SECONDS).get("success"));}finally{pool.shutdownNow();}assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound",Integer.class));}
}
